const configs = tool("configs", {});

const notes = [];
for (const cfg of configs) {
  notes.push(cfg.owner_note);
}

const priorities = tool("judge_priorities", { notes });

function parseTimeout(t) {
  if (typeof t === "number") {
    return Math.round(t * 1000);
  }
  const s = String(t).trim();
  const m = s.match(/^(\d+(?:\.\d+)?)(ms|s|m)?$/);
  if (!m) return 0;
  const val = parseFloat(m[1]);
  const unit = m[2] || "s";
  if (unit === "ms") return Math.round(val);
  if (unit === "m") return Math.round(val * 60000);
  return Math.round(val * 1000);
}

function parseEndpoint(ep) {
  const s = String(ep).trim();
  const idx = s.lastIndexOf(":");
  if (idx === -1) {
    return { host: s, port: 443 };
  }
  const host = s.slice(0, idx);
  const portStr = s.slice(idx + 1);
  const port = parseInt(portStr, 10);
  return { host: host, port: isNaN(port) ? 443 : port };
}

function parseRetries(r) {
  if (r === undefined || r === null || r === "") return 0;
  const n = parseInt(String(r).trim(), 10);
  return isNaN(n) ? 0 : n;
}

function parseTags(tags) {
  let arr = [];
  if (Array.isArray(tags)) {
    arr = tags;
  } else if (typeof tags === "string") {
    arr = tags.split(",");
  }
  const set = new Set();
  for (const t of arr) {
    const v = String(t).trim().toLowerCase();
    if (v !== "") set.add(v);
  }
  return Array.from(set).sort();
}

function parseEnabled(e) {
  if (typeof e === "boolean") return e;
  if (typeof e === "number") return e !== 0;
  const s = String(e).trim().toLowerCase();
  return s === "yes" || s === "true" || s === "on" || s === "1";
}

const result = [];
for (let i = 0; i < configs.length; i++) {
  const cfg = configs[i];
  const ep = parseEndpoint(cfg.endpoint);
  result.push({
    name: cfg.name,
    timeoutMs: parseTimeout(cfg.timeout),
    host: ep.host,
    port: ep.port,
    retries: parseRetries(cfg.retries),
    tags: parseTags(cfg.tags),
    enabled: parseEnabled(cfg.enabled),
    priority: priorities[i],
  });
}

result;

